            {"Q_el_proposal","Q_areal/3600[s/h]"},{"i_1C","Q_areal/1[h]"},{"C_rate","0.1"},
            {"i_app","C_rate*i_1C"},{"sigma_short","1e-20[S/m]"}
        };
